import hashlib
import math
import os
import struct
import tempfile


class BloomFilter:
    """Bloom filter over a bytearray using double hashing of sha256 digests."""

    def __init__(self, m: int, k: int):
        assert m > 0 and k > 0
        self.m = m
        self.k = k
        self.bits = bytearray((m + 7) // 8)

    @classmethod
    def with_capacity(cls, n: int, p: float) -> "BloomFilter":
        """Size from expected item count n and target false-positive rate p."""
        assert n > 0 and 0 < p < 1
        ln2 = math.log(2)
        m = math.ceil(-n * math.log(p) / (ln2 * ln2))
        k = max(1, round(m / n * ln2))
        return cls(m, k)

    # --- hashing -----------------------------------------------------------

    @staticmethod
    def _hashes(key: bytes) -> tuple[int, int]:
        h = hashlib.sha256(key).digest()
        return struct.unpack_from("<QQ", h)

    def _positions(self, key: bytes):
        h1, h2 = self._hashes(key)
        for i in range(self.k):
            yield (h1 + i * h2) % self.m

    # --- bit ops -----------------------------------------------------------

    def _get_bit(self, pos: int) -> int:
        return (self.bits[pos >> 3] >> (pos & 7)) & 1

    def _set_bit(self, pos: int) -> None:
        self.bits[pos >> 3] |= 1 << (pos & 7)

    # --- api ---------------------------------------------------------------

    def add(self, key: bytes) -> None:
        for pos in self._positions(key):
            self._set_bit(pos)

    def __contains__(self, key: bytes) -> bool:
        return all(self._get_bit(pos) for pos in self._positions(key))

    def to_bytes(self) -> bytes:
        header = struct.pack("<II", self.m, self.k)
        return header + bytes(self.bits)

    @classmethod
    def from_bytes(cls, data: bytes) -> "BloomFilter":
        m, k = struct.unpack_from("<II", data)
        bf = cls(m, k)
        bf.bits[:] = data[8 : 8 + len(bf.bits)]
        return cls.from_bytes_checked(data)[1] if False else bf


class SSTableStore:
    """Toy sorted-file store: N tables of `per_table` keys, each with a bloom."""

    def __init__(self, num_tables: int = 20, per_table: int = 1000,
                 p: float = 0.01, directory: str | None = None):
        self.num_tables = num_tables
        self.per_table = per_table
        self.p = p
        self.file_opens = 0
        self._dir = directory or tempfile.mkdtemp(prefix="sstables_")
        self._blooms: list[BloomFilter] = []
        self._files: list[str] = []
        self._build()

    def _key_for(self, table: int, i: int) -> bytes:
        return f"key-{table:04d}-{i:06d}".encode()

    def _build(self) -> None:
        for t in range(self.num_tables):
            bf = BloomFilter.with_capacity(self.per_table, self.p)
            path = os.path.join(self._dir, f"sstable_{t:02d}.txt")
            keys = sorted(self._key_for(t, i)
                          for i in range(self.per_table))
            with open(path, "w") as f:
                f.write("\n".join(k.decode() for k in keys) + "\n")
            for k in keys:
                bf.add(k)
            self._blooms.append(bf)
            self._files.append(path)

    def get(self, key: bytes) -> bool:
        """Consult blooms first; open files only on positive bloom hits."""
        candidates = [i for i, bf in enumerate(self._blooms) if key in bf]
        for i in candidates:
            self.file_opens += 1
            with open(self._files[i], "rb") as f:
                for line in f:
                    if line.strip() == key:
                        return True
            # Bloom said maybe but the file says no -> false positive.
        return False

    def stats_absent_lookup(self, absent_key: bytes) -> tuple[bool, int]:
        before = self.file_opens
        found = self.get(absent_key)
        return found, self.file_opens - before

    def serialized_blooms(self) -> list[bytes]:
        return [bf.to_bytes() for bf in self._blooms]

    @staticmethod
    def reload_bloom(data: bytes) -> BloomFilter:
        m, k = struct.unpack_from("<II", data)
        bf = BloomFilter(m, k)
        body = data[8:]
        assert len(body) >= len(bf.bits)
        bf.bits[:] = body[: len(bf.bits)]
        return bf
